from pathlib import Path
report=json.loads(Path(sys.argv[1]).read_text())['files']
p='python/carnot/verify/development_methods_8098.py'
tree=ast.parse(Path(p).read_text())
fn=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='methods')
lines={n.lineno for n in ast.walk(fn.body[1]) if isinstance(n,ast.stmt)}
lines.update(n.lineno for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id in {'METHOD_PATH','METHOD_SHA256'} for t in n.targets))
scopes={p:lines}
p='python/carnot/experiment_8098_v701_development_methods.py'
scopes[p]={n.lineno for n in ast.parse(Path(p).read_text()).body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='DESIGN' for t in n.targets)}
p='python/carnot/reporting/methods_stream_execution_8111.py'
scopes[p]={n.lineno for n in ast.walk(ast.parse(Path(p).read_text())) if isinstance(n,ast.Expr) and isinstance(n.value,ast.Call) and isinstance(n.value.func,ast.Attribute) and n.value.func.attr=='add_argument' and n.value.args and isinstance(n.value.args[0],ast.Constant) and n.value.args[0].value=='--date'}
for p,lines in scopes.items():
    missing=lines.intersection(report[p]['missing_lines'])
    assert lines and not missing,(p,sorted(missing))
    print(p, 'changed statements=',len(lines),'coverage=100%',flush=True)

